import os
import torch


class Config:
    """
    Configuration for the Topology-Informed Stabilized Recurrent Network (TI-SRN).
    """

    # ==============================
    # General Settings
    # ==============================
    seed = 42
    device = "cuda" if torch.cuda.is_available() else "cpu"
    num_workers = 2

    # ==============================
    # Data Paths
    # ==============================
    # Metadata files generated by the provided script
    train_csv = "./metadata/train.csv"
    val_csv = "./metadata/val.csv"
    test_csv = "./metadata/test.csv"

    # Sample submission for formatting
    sample_submission = "./input/sample_submission.csv"

    # Cache Directory for this specific idea (Idea 43)
    cache_dir = "./working/idea_43/"
    train_cache = os.path.join(cache_dir, "train_data_ti_srn_v1.npz")
    val_cache = os.path.join(cache_dir, "val_data_ti_srn_v1.npz")
    test_cache = os.path.join(cache_dir, "test_data_ti_srn_v1.npz")

    # ==============================
    # Data Dimensions & Features
    # ==============================
    seq_len = 107
    pred_len = 68

    # Input Feature Channels:
    # 1. Sequence One-Hot (A, G, C, U) -> 4
    # 2. Structure One-Hot (., (, )) -> 3
    # 3. Loop Type One-Hot (S, M, I, B, H, E, X) -> 7
    # 4. Partner Identity One-Hot (A, G, C, U, None/Pad) -> 4 (Assuming 0-vector for unpaired)
    input_channels = 4 + 3 + 7 + 4  # Total: 18

    # ==============================
    # Model Architecture
    # ==============================
    # 1. Main Backbone (Static Dense Dilated TCN)
    backbone_channels = 64
    backbone_dilations = [1, 2, 4, 8, 16, 32]
    backbone_kernel_size = 3
    pointwise_kernel_size = 1
    backbone_dropout = 0.1

    # Latent projection dimension after backbone
    latent_dim = 64

    # 2. Topology-Informed Feedback Module
    # Inputs: Recycled Preds (5) + Raw Topology (Structure 3 + Loop 7 = 10)
    feedback_input_channels = 5 + 10  # Total: 15
    feedback_channels = 32
    feedback_dilations = [1, 2, 4]  # Lightweight stack

    # 3. Aggregation Head
    # Interaction: Concatenates Self [Z, E_fb] and Partner [Z, E_fb]
    # Input to RNN = (Latent 64 + Feedback 32) * 2 = 192
    rnn_hidden_dim = 128
    rnn_layers = 1
    bidirectional = True

    # ==============================
    # Training Hyperparameters
    # ==============================
    epochs = 50
    batch_size = 32
    lr = 1e-3
    weight_decay = 1e-4

    # Scheduler
    scheduler_patience = 5
    scheduler_factor = 0.5

    # Early Stopping
    early_stopping_patience = 10

    # Loss Weights
    # Loss = MCRMSE(Pass2) + aux_weight * MCRMSE(Pass1)
    aux_loss_weight = 0.5

    # ==============================
    # Targets
    # ==============================
    # All target columns provided in training data
    target_cols = ["reactivity", "deg_Mg_pH10", "deg_pH10", "deg_Mg_50C", "deg_50C"]

    # The specific columns used for the competition metric
    scored_cols = ["reactivity", "deg_Mg_pH10", "deg_Mg_50C"]

    def __init__(self, debug=False):
        """
        Initialize config, optionally overriding for debug mode.
        """
        self.debug = debug

        # Create cache directory if it doesn't exist
        os.makedirs(self.cache_dir, exist_ok=True)

        if self.debug:
            print("WARNING: Debug mode enabled. Reducing epochs and batch size.")
            self.epochs = 2
            self.batch_size = 4
            # Use separate cache files for debug to avoid overwriting full data
            self.train_cache = os.path.join(self.cache_dir, "debug_train.npz")
            self.val_cache = os.path.join(self.cache_dir, "debug_val.npz")
            self.test_cache = os.path.join(self.cache_dir, "debug_test.npz")
